import React from 'react';

function App() {
  const data = [
    { month: 'Jan', value: 65 },
    { month: 'Fev', value: 85 },
    { month: 'Mar', value: 45 },
    { month: 'Abr', value: 90 },
    { month: 'Mai', value: 70 },
  ];

  return (
    <div className="p-8 bg-gray-100 min-h-screen">
      <div className="max-w-4xl mx-auto bg-white p-6 rounded-lg shadow">
        <h1 className="text-2xl font-bold mb-6 text-center">Vendas Mensais 2024</h1>

        <div className="h-96 flex items-end justify-around mb-8 relative">
          {/* Add grid lines */}
          <div className="absolute inset-0 grid grid-rows-4 w-full">
            {[...Array(5)].map((_, i) => (
              <div key={i} className="border-t border-gray-100" />
            ))}
          </div>

          {data.map((item, index) => (
            <div key={index} className="flex flex-col items-center w-20 relative z-10">
              <div 
                className="w-16 bg-blue-500 transition-all hover:bg-blue-600 rounded-t-lg"
                style={{ 
                  height: `${item.value}%`,
                  minHeight: '20px'
                }}
              />
              <span className="mt-2 font-medium">{item.month}</span>
              <span className="text-sm text-gray-600 font-medium">{item.value}%</span>
            </div>
          ))}
        </div>

        <div className="grid grid-cols-3 gap-4">
          <div className="bg-blue-100 p-4 rounded">
            <h3>Média</h3>
            <p className="text-2xl font-bold text-blue-600">71%</p>
          </div>
          <div className="bg-green-100 p-4 rounded">
            <h3>Máximo</h3>
            <p className="text-2xl font-bold text-green-600">90%</p>
          </div>
          <div className="bg-red-100 p-4 rounded">
            <h3>Mínimo</h3>
            <p className="text-2xl font-bold text-red-600">45%</p>
          </div>
        </div>
      </div>
    </div>
  );
}

export default App;
